SELECT EXISTS(SELECT 1 FROM refresh_tokens
    WHERE user_id = #{userId} AND token_hash = #{tokenHash}
      AND expires_at IS NULL AND revoked_at IS NULL)

SELECT id, user_id, token_hash, session_id, expires_at, revoked_at, revoke_reason, created_at
FROM refresh_tokens
WHERE id = #{id}

SELECT id, user_id, token_hash, session_id, expires_at, revoked_at, revoke_reason, created_at
FROM refresh_tokens
WHERE token_hash = #{tokenHash}
